  preheader: "3 Money EQ graduates who upgraded to the collection. What happened to their income — and their peace — is worth seeing.",
  img: 'https://storyblok-cdn.mindvalley.com/f/60579/1920x1080/0de0b1e34e/meq_questcover_en.jpg',
